    const connectionStatus = deviceDetails?.['ConnectionStatus'] ?? '';
    if (connectionStatus.toLowerCase() !== 'connected') {
      throw new Error(`Meter ConnectionStatus is '${connectionStatus}', not Connected`);
    }

